package org.apache.commons.math3.analysis.differentiation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DSCompiler_atan2_TriageGen2Test {

    private static final double EPSILON = 1e-12;

    @Test
    public void testAtan2_Quadrant1() {
        // x > 0, y > 0
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {1.0};
        double[] x = {1.0};
        double[] result = new double[1];

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(1.0, 1.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2_Quadrant2() {
        // x < 0, y > 0
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {1.0};
        double[] x = {-1.0};
        double[] result = new double[1];

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(1.0, -1.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2_Quadrant3() {
        // x < 0, y < 0
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {-1.0};
        double[] x = {-1.0};
        double[] result = new double[1];

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(-1.0, -1.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2_Quadrant4() {
        // x > 0, y < 0
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {-1.0};
        double[] x = {1.0};
        double[] result = new double[1];

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(-1.0, 1.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2_BoundaryXZero() {
        // x = 0 (treated as x >= 0 in code logic)
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {1.0};
        double[] x = {0.0};
        double[] result = new double[1];

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(1.0, 0.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2_MultipleElements() {
        // Test array size > 1 to cover the loop in both branches
        DSCompiler compiler = DSCompiler.getCompiler(2, 0);
        double[] y = {1.0, -1.0};
        double[] x = {1.0, -1.0}; // First x is positive, second is negative
        // Note: The current implementation of atan2 uses x[xOffset] to decide the branch for the WHOLE array.
        // This is a structural characteristic of the provided code.

        double[] result = new double[2];

        // Case 1: x[0] >= 0
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(1.0, 1.0), result[0], EPSILON);
        Assert.assertEquals(FastMath.atan2(-1.0, -1.0), result[1], EPSILON);

        // Case 2: x[0] < 0
        double[] xNeg = {-1.0, -1.0};
        compiler.atan2(y, 0, xNeg, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(1.0, -1.0), result[0], EPSILON);
        Assert.assertEquals(FastMath.atan2(-1.0, -1.0), result[1], EPSILON);
    }

    @Test
    public void testAtan2_Offsets() {
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {0.0, 1.0};
        double[] x = {0.0, 1.0};
        double[] result = {0.0, 0.0, 0.0};

        // Use yOffset=1, xOffset=1, resultOffset=1
        compiler.atan2(y, 1, x, 1, result, 1);

        Assert.assertEquals(FastMath.atan2(1.0, 1.0), result[1], EPSILON);
    }

    @Test
    public void testAtan2_NegativeZeroInBranch() {
        // To hit the (tmp2[0] <= 0) branch inside the x < 0 block
        // We need y/ (r-x) to be <= 0. If x is negative, r-x is positive. 
        // So we need y <= 0.
        DSCompiler compiler = DSCompiler.getCompiler(1, 0);
        double[] y = {-1.0};
        double[] x = {-1.0};
        double[] result = new double[1];

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(-1.0, -1.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }
}
